settings.custom_liquid:
{% comment %}
Custom Liquids — Banners countdown + oferta
Grupo Header → 1 Custom liquid → ARRIBA del Header
{% endcomment %}

<style>
  /* ===== COLORES — edita solo esto ===== */
  #cl-stack{
    --cd-c1:#3b1d6e;
    --cd-c2:#6b3cb8;
    --cd-c3:#2a1450;
    --cd-text:#fff;
    --cd-box:#fff;
    --cd-num:#1a1028;
    --cd-lab:#4a2a86;
    --of-c1:#cbb7f2;
    --of-c2:#e8defb;
    --of-c3:#b39de6;
    --of-text:#1a1028;
  }
  /* ==================================== */

  #cl-stack{isolation:isolate;width:100%;margin:0}
  #cl-cd{
    padding:9px 12px;
    display:flex;align-items:center;justify-content:center;gap:10px;flex-wrap:wrap;
    color:var(--cd-text);
    font:700 12px/1.2 system-ui,-apple-system,sans-serif;
    letter-spacing:.06em;text-transform:uppercase;
    background:linear-gradient(90deg,var(--cd-c1),var(--cd-c2),var(--cd-c3),var(--cd-c1));
    background-size:300% 100%;
    animation:clCdGrad 8s ease infinite;
    box-sizing:border-box;
  }
  #cl-cd .cl-cd__clock{display:flex;align-items:center;gap:6px}
  #cl-cd .cl-cd__box{background:var(--cd-box);color:var(--cd-num);min-width:46px;padding:4px 6px 3px;border-radius:4px;text-align:center;line-height:1}
  #cl-cd .cl-cd__n{display:block;font-size:15px;font-weight:800;letter-spacing:0}
  #cl-cd .cl-cd__l{display:block;margin-top:2px;font-size:8px;color:var(--cd-lab);letter-spacing:.08em}
  #cl-cd .cl-cd__sep{opacity:.7;font-weight:800}
  #cl-of{
    padding:8px 12px;
    display:flex;align-items:center;justify-content:center;
    color:var(--of-text);
    font:800 13px/1.2 system-ui,-apple-system,sans-serif;
    letter-spacing:.04em;text-transform:uppercase;text-align:center;
    background:linear-gradient(90deg,var(--of-c1),var(--of-c2),var(--of-c3),var(--of-c1));
    background-size:300% 100%;
    animation:clOfGrad 9s ease infinite;
    box-sizing:border-box;
  }
  @keyframes clCdGrad{0%{background-position:0% 50%}50%{background-position:100% 50%}100%{background-position:0% 50%}}
  @keyframes clOfGrad{0%{background-position:0% 50%}50%{background-position:100% 50%}100%{background-position:0% 50%}}
  @media (max-width:749px){
    #cl-cd{padding:8px 8px;font-size:11px;gap:7px}
    #cl-cd .cl-cd__box{min-width:40px;padding:3px 4px}
    #cl-cd .cl-cd__n{font-size:13px}
    #cl-of{padding:7px 8px;font-size:11px}
  }

  .shopify-section:has(#cl-stack){
    margin:0 !important;
    padding:0 !important;
    position:sticky !important;
    top:0 !important;
    z-index:14 !important;
  }
  #cl-header-spacer{width:100%;pointer-events:none}
  #MainContent .product__media-wrapper,
  #MainContent .product__info-container,
  #MainContent .product-media-container,
  #MainContent .sticky-content,
  #MainContent [class*="product"][class*="sticky"]{
    position:relative !important;
    top:auto !important;
  }
</style>

<div id="cl-stack">
  <div id="cl-cd">
    <span id="cl-cd-txt">La oferta termina en</span>
    <div class="cl-cd__clock">
      <div class="cl-cd__box"><span class="cl-cd__n" id="cl-h">00</span><span class="cl-cd__l">hrs</span></div>
      <span class="cl-cd__sep">:</span>
      <div class="cl-cd__box"><span class="cl-cd__n" id="cl-m">27</span><span class="cl-cd__l">min</span></div>
      <span class="cl-cd__sep">:</span>
      <div class="cl-cd__box"><span class="cl-cd__n" id="cl-s">18</span><span class="cl-cd__l">seg</span></div>
    </div>
  </div>
  <div id="cl-of">Por tiempo limitado: hasta 48% off</div>
</div>

<script>
(function(){
  var DURATION_MS = (27 * 60 + 18) * 1000; /* 27 min 18 seg */
  var STORAGE_KEY = 'cl_oferta_end_v1';

  var hEl = document.getElementById('cl-h');
  var mEl = document.getElementById('cl-m');
  var sEl = document.getElementById('cl-s');
  var tEl = document.getElementById('cl-cd-txt');

  function pad(n){ return n < 10 ? '0'+n : ''+n; }

  function getEnd(){
    var now = Date.now();
    try {
      var saved = parseInt(localStorage.getItem(STORAGE_KEY), 10);
      if (saved && saved > now) return saved;
    } catch(e){}
    var next = now + DURATION_MS;
    try { localStorage.setItem(STORAGE_KEY, String(next)); } catch(e){}
    return next;
  }

  function tick(){
    if(!hEl) return;
    var d = getEnd() - Date.now();
    if(d < 0) d = 0;
    hEl.textContent = pad(Math.floor(d / 36e5));
    mEl.textContent = pad(Math.floor((d % 36e5) / 6e4));
    sEl.textContent = pad(Math.floor((d % 6e4) / 1000));
    if(tEl) tEl.textContent = 'La oferta termina en';
  }

  tick();
  setInterval(tick, 1000);

  function findHeader(barSec){
    var n = barSec.nextElementSibling;
    while(n){
      if(n.querySelector && n.querySelector('sticky-header, .header-wrapper, header, .header')) return n;
      n = n.nextElementSibling;
    }
    var sh = document.querySelector('sticky-header');
    return sh ? sh.closest('.shopify-section') : null;
  }

  function pin(){
    var stack = document.getElementById('cl-stack');
    if(!stack) return;
    var barH = stack.offsetHeight;
    var barSec = stack.closest('.shopify-section');
    if(barSec){
      barSec.style.setProperty('position','sticky','important');
      barSec.style.setProperty('top','0px','important');
      barSec.style.setProperty('z-index','14','important');
    }
    var headerSec = findHeader(barSec);
    if(!headerSec) return;

    headerSec.style.setProperty('position','fixed','important');
    headerSec.style.setProperty('top', barH + 'px','important');
    headerSec.style.setProperty('left','0','important');
    headerSec.style.setProperty('right','0','important');
    headerSec.style.setProperty('width','100%','important');
    headerSec.style.setProperty('z-index','13','important');
    headerSec.style.setProperty('transform','none','important');
    headerSec.style.background = headerSec.style.background || '#fff';

    headerSec.querySelectorAll('sticky-header, .header-wrapper').forEach(function(el){
      el.style.setProperty('position','relative','important');
      el.style.setProperty('top','0','important');
      el.style.setProperty('transform','none','important');
    });

    var spacer = document.getElementById('cl-header-spacer');
    if(!spacer){
      spacer = document.createElement('div');
      spacer.id = 'cl-header-spacer';
      headerSec.parentNode.insertBefore(spacer, headerSec.nextSibling);
    }
    spacer.style.height = headerSec.offsetHeight + 'px';
  }

  pin();
  window.addEventListener('load', pin);
  window.addEventListener('resize', pin);
})();
</script>
